<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">Downloads</p><h1>Documents</h1><p>Upload, publish, revise metadata, archive, and restore downloadable files.</p></div><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/documents/create">Upload document</a></section><section class="admin-card"><div class="table-wrap"><table><thead><tr><th>Document</th><th>Visibility</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($items===[]):?><tr><td colspan="4">No documents yet.</td></tr><?php endif;?><?php foreach($items as$i):?><tr><td><strong><?=View::escape($i['title'])?></strong><br><small><?=View::escape($i['type_name']??$i['original_name'])?> · <?=number_format((int)$i['file_size']/1024)?> KB</small></td><td><?=$i['is_public']?'Public':'Internal'?></td><td><?=View::escape($i['status'])?></td><td><div class="table-actions"><a href="<?=View::escape($baseUrl)?>admin/documents/<?=(int)$i['id']?>/edit">Edit</a><?php $a=$i['status']==='published'?'archive':($i['status']==='archived'?'restore':'publish');?><form method="post" action="<?=View::escape($baseUrl)?>admin/documents/<?=(int)$i['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$a?>"><?=ucfirst($a)?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
